  "nav.SpyDeck": "SpyDeck",
  // ── Chat ──────────────────────────────────────────────────────────────────
  // Keyed by the English string (useLabelT), so English needs no side here.
  // Product names are left alone: EGFUL, EG Channel, PDF, AI.
  "chat.Conversations": "Cuộc trò chuyện",
