  "orders.The warehouse has this item. You can still stop it if the artwork is wrong.": "Kho đã có sản phẩm này. Bạn vẫn có thể dừng lại nếu thiết kế sai.",
  "orders.Leave it if each line needs its own customisation — that’s the usual case for a multi-colour order.":
    "Hãy để nguyên nếu mỗi dòng cần tuỳ chỉnh riêng — đây là trường hợp thường gặp với đơn nhiều màu.",
  "orders.Nothing matches exactly, but these look similar. Check one before paying for the same work twice.":
    "Không có kết quả trùng khớp hoàn toàn, nhưng những mẫu này trông tương tự. Hãy kiểm tra trước khi trả tiền hai lần cho cùng một công việc.",
  "orders.The same artwork has already been digitised. Reuse that file instead of sending this to a designer again — the seller sees a normal deliverable on their own order and nothing about where it came from.":
    "Thiết kế này đã được số hoá trước đó. Hãy dùng lại tệp đó thay vì gửi cho nhà thiết kế lần nữa — người bán vẫn thấy sản phẩm bàn giao bình thường trên đơn của họ và không biết tệp đến từ đâu.",
  "orders.Each stage is a record that the work was done. Only catch up when it really was — the floor and the seller both read this as what happened.":
    "Mỗi công đoạn là một bản ghi rằng công việc đã được làm. Chỉ cập nhật bù khi việc đó thực sự đã xong — cả xưởng lẫn người bán đều đọc đây là điều đã xảy ra.",
  "orders.Street and postcode are held by the factory — ask support if an order needs checking.":
    "Địa chỉ và mã bưu chính do xưởng giữ — hãy liên hệ hỗ trợ nếu cần kiểm tra một đơn hàng.",

