  "branding.512&times;512 PNG": "PNG 512×512",
  "branding.Shown on the phone home screen, which fits about 12 characters.": "Hiển thị trên màn hình chính của điện thoại, vừa khoảng 12 ký tự.",
  "branding.Used on emails and printed sheets. A wide PNG or SVG with transparent ground.": "Dùng trong email và các bản in. Ảnh PNG hoặc SVG khổ ngang, nền trong suốt.",
  "branding.The browser tab, the phone home screen and the installed app. Upload one": "Tab trình duyệt, màn hình chính điện thoại và ứng dụng đã cài. Hãy tải lên một ảnh",
  "branding., square, mark centred — everything else is scaled from it.": ", vuông, biểu tượng đặt giữa — mọi kích thước khác đều được suy ra từ ảnh này.",
  "branding.Saves the moment you upload — no Save needed. The tab may take a minute to catch up, and a hard reload is instant.": "Lưu ngay khi bạn tải lên — không cần bấm Lưu. Tab trình duyệt có thể mất một phút để cập nhật, tải lại trang cứng thì thấy ngay.",
  "branding.The palette and the accent are chosen from presets that have been measured, never typed as a colour. What a preset cannot reach is set in code:": "Bảng màu và màu nhấn được chọn từ các bộ đã được đo kiểm, không bao giờ nhập tay mã màu. Những gì bộ có sẵn không làm được thì đặt trong mã nguồn:",
  "branding.inks around 247 pieces of text as well as filling buttons, and the status colours (shipped, hold, alert) carry meaning on the floor — so a free picker could make a quarter of the app unreadable without anyone noticing. Ask for another preset and it can be added properly, with the contrast measured.": "tô màu cho khoảng 247 đoạn chữ đồng thời làm nền cho các nút, và các màu trạng thái (đã gửi, tạm giữ, cảnh báo) mang ý nghĩa ngoài xưởng — nên một bộ chọn màu tự do có thể khiến một phần tư ứng dụng không đọc được mà không ai nhận ra. Hãy yêu cầu thêm một bộ màu mới và nó sẽ được bổ sung đúng cách, có đo độ tương phản.",
