  "designMaker.Upload an image and it stays here to reuse.": "Tải một ảnh lên và nó sẽ ở lại đây để dùng lại.",
  "designMaker.Artwork buyers send with an order lands here on its own.": "Thiết kế người mua gửi kèm đơn hàng sẽ tự về đây.",
  "designMaker.Save a design as a template to reopen it on any blank.": "Lưu một thiết kế thành mẫu để mở lại trên bất kỳ phôi nào.",
  "designMaker.A flattened picture you can place on anything. Does not reopen.": "Một ảnh đã làm phẳng, đặt được lên bất cứ thứ gì. Không mở lại để sửa được.",
  "designMaker.The layers, the blank and the print area, every side. Reopens in the editor.": "Toàn bộ lớp, phôi và vùng in của mọi mặt. Mở lại được trong trình chỉnh sửa.",
  "designMaker.Pick a blank, then place artwork or add text from the tools on the left. Select a layer and its controls appear here.": "Chọn một phôi, rồi đặt thiết kế hoặc thêm chữ từ bộ công cụ bên trái. Chọn một lớp và các tuỳ chỉnh của nó sẽ hiện ở đây.",
  "designMaker.Added text lands in the middle of the print area. Select it on the canvas to change the words, size and colour — the controls are on the right, with the rest of the layer.": "Chữ vừa thêm sẽ nằm giữa vùng in. Chọn nó trên khung vẽ để đổi nội dung, cỡ và màu — các tuỳ chỉnh nằm bên phải, cùng với phần còn lại của lớp.",

