  "publish.One shop is in dry-run mode: it will be validated and nothing will be sent.": "Một cửa hàng đang ở chế độ chạy thử: dữ liệu sẽ được kiểm tra và không có gì được gửi đi.",
  "publish.Finished — with one shop that sent nothing": "Đã xong — nhưng có một cửa hàng không gửi gì",
  "publish.There’s nothing to publish here.": "Không có gì để đăng ở đây.",
  "publish.A brand name is": "Tên thương hiệu là",
  "publish.Enter a retail price to see profit per size.": "Nhập giá bán lẻ để xem lợi nhuận theo từng cỡ.",
  "publish.Retail is per size — leave a row blank to use the price above. Profit updates as you type.": "Giá bán lẻ đặt theo từng cỡ — để trống một dòng thì dùng giá ở trên. Lợi nhuận cập nhật khi bạn nhập.",
  "publish.Sizes shown in red sell at a loss at this retail price.": "Các cỡ hiển thị màu đỏ đang bán lỗ ở mức giá này.",
  "publish.This sells at a loss — raise the retail price.": "Mức này đang bán lỗ — hãy tăng giá bán lẻ.",
  "publish.Some sizes have no price set on the blank — add pricing in Products.": "Một số cỡ chưa được đặt giá trên phôi — hãy thêm giá trong mục Sản phẩm.",
  "publish.That blank has no price set, so we can’t work out a margin. Add pricing to it in Products.": "Phôi đó chưa được đặt giá nên không tính được biên lợi nhuận. Hãy thêm giá cho nó trong mục Sản phẩm.",
  "publish.With none selected this publishes as a flat listing with no variants.": "Nếu không chọn gì, tin đăng sẽ được đăng dạng phẳng, không có phiên bản.",
  "publish.Sets what we produce, and the cost behind your margin.": "Quyết định thứ chúng tôi sản xuất, và chi phí tạo nên biên lợi nhuận của bạn.",
  "publish.Pick a base product. Without one this publishes with no cost, no margin and no variant SKUs we recognise — the order it creates won’t price or reach the factory.": "Hãy chọn một sản phẩm gốc. Nếu không, tin đăng sẽ không có chi phí, không có biên lợi nhuận và không có mã SKU phiên bản mà chúng tôi nhận ra — đơn hàng tạo ra sẽ không tính được giá và không về được xưởng.",
  "publish.Etsy activates after the photos upload — if it refuses, the listing stays a draft and we’ll say why.": "Etsy kích hoạt tin đăng sau khi ảnh tải lên xong — nếu bị từ chối, tin đăng vẫn ở dạng nháp và chúng tôi sẽ cho biết lý do.",
  "publish.No shop is connected to your account yet, so there’s nowhere to publish this. Connect one under": "Chưa có cửa hàng nào được kết nối với tài khoản của bạn, nên không có nơi để đăng. Hãy kết nối một cửa hàng ở mục",
  "publish.A publish page is opened from a product — and the draft it carried is gone, which happens when the tab was closed or this link came from somewhere else. Start again from the board you were on.": "Trang đăng bán được mở từ một sản phẩm — và bản nháp nó mang theo đã mất, điều này xảy ra khi tab bị đóng hoặc liên kết này đến từ nơi khác. Hãy bắt đầu lại từ bảng bạn đang làm việc.",

