  "inventory.Track stock per variant, flag low/out, and print SKU barcodes.": "Theo dõi tồn kho theo từng phiên bản, cảnh báo sắp hết/hết hàng, và in mã vạch SKU.",
  "inventory.Internal only — nothing outside the factory sees this SKU.": "Chỉ nội bộ — không ai ngoài xưởng nhìn thấy mã SKU này.",
  "inventory.Published in the partner stock feed.": "Được công bố trong nguồn dữ liệu tồn kho cho đối tác.",
  "inventory.Cleared for unauthenticated surfaces too. Nothing reads that yet — this records the decision.": "Cho phép cả trên các trang không cần đăng nhập. Hiện chưa có nơi nào đọc mục này — đây chỉ là ghi nhận quyết định.",
  "inventory.No catalogue product has a SKU yet — stock is held against it, so add one on the product first.": "Chưa có sản phẩm nào trong danh mục có mã SKU — tồn kho được giữ theo mã này, nên hãy thêm SKU cho sản phẩm trước.",
  "inventory.Phone camera: use the square code. Handheld gun: either. Hold 15–25cm away and turn screen brightness up if it won’t read.": "Camera điện thoại: dùng mã vuông. Máy quét cầm tay: mã nào cũng được. Giữ cách 15–25cm và tăng độ sáng màn hình nếu không quét được.",
