  "campaigns.No ad platform keys are set yet, so there is nothing to read.": "Chưa đặt khoá cho nền tảng quảng cáo nào, nên không có dữ liệu để đọc.",
  "campaigns.Keys are set. Connect an ad account to pull its campaigns.": "Đã đặt khoá. Hãy kết nối một tài khoản quảng cáo để lấy các chiến dịch của nó.",
  "campaigns.Connect buttons activate once the provider approvals land — the OAuth exchange is wired and waiting.": "Các nút kết nối sẽ hoạt động khi nhà cung cấp phê duyệt — phần trao đổi OAuth đã đấu nối xong và đang chờ.",
