  "broadcasts.There is no unsend. Read the number below before you confirm.": "Không thể thu hồi. Hãy đọc con số bên dưới trước khi xác nhận.",
  "broadcasts.Drafts are open to the team; sending is admin and operator only. There is no unsend.": "Cả nhóm đều soạn được bản nháp; chỉ quản trị và điều hành mới gửi được. Không thể thu hồi.",
