  "broadcasts.Your saved branding": "Thương hiệu đã lưu của bạn",
  "broadcasts.Footer note (optional)": "Ghi chú chân trang (không bắt buộc)",
  "broadcasts.Optional — falls back to the wordmark.": "Không bắt buộc — nếu để trống sẽ dùng chữ ký thương hiệu.",
  "broadcasts.Logo, colour and footer — applied to every broadcast email.": "Logo, màu sắc và chân trang — áp dụng cho mọi email hàng loạt.",
  "broadcasts.Saved — applies to the next send.": "Đã lưu — áp dụng cho lần gửi tiếp theo.",
  "broadcasts.A tagline or seasonal note. Shown above the required unsubscribe line.": "Một câu khẩu hiệu hoặc ghi chú theo mùa. Hiển thị phía trên dòng huỷ đăng ký bắt buộc.",
  "broadcasts.Hi Alex,": "Chào Alex,",
  "broadcasts.What's new this month": "Có gì mới trong tháng này",
  "broadcasts.Your message appears here…": "Nội dung của bạn sẽ hiện ở đây…",
  "broadcasts.Your broadcast copy appears here…": "Nội dung email hàng loạt của bạn sẽ hiện ở đây…",
  "broadcasts.Unsubscribe from updates like this": "Huỷ nhận các cập nhật như thế này",
  "broadcasts.You’re receiving this because you have an EGFUL seller account.": "Bạn nhận được email này vì bạn có tài khoản người bán EGFUL.",
  "broadcasts.No seller has unsubscribed yet.": "Chưa có người bán nào huỷ đăng ký.",
  "broadcasts.s have": "đã",
  "broadcasts.on the server.": "trên máy chủ.",
  "broadcasts.No mail transport is configured, so nothing can be sent. Set": "Chưa cấu hình dịch vụ gửi thư nên không gửi được gì. Hãy đặt",
  "broadcasts.Full message with your branding and the unsubscribe footer.": "Toàn bộ nội dung email kèm thương hiệu của bạn và chân trang huỷ đăng ký.",
  "broadcasts.Written as plain text. An unsubscribe footer is added automatically — it is required, so it is not optional here.": "Viết dưới dạng văn bản thuần. Chân trang huỷ đăng ký được thêm tự động — đây là mục bắt buộc nên không thể tắt.",
  "broadcasts.Added addresses get a real unsubscribe link — opting out suppresses that address for good, account or not.": "Các địa chỉ được thêm vào đều nhận liên kết huỷ đăng ký thật — khi huỷ, địa chỉ đó bị loại vĩnh viễn, dù có tài khoản hay không.",
  "broadcasts.Anyone who has unsubscribed is excluded automatically, and the list is resolved again when you send, so an unsubscribe between now and then is still honoured.": "Bất kỳ ai đã huỷ đăng ký đều tự động bị loại, và danh sách được xác định lại lúc bạn bấm gửi, nên một lượt huỷ đăng ký từ giờ đến lúc đó vẫn được tôn trọng.",
  "broadcasts.Subject and body only, to the seller’s notifications. Goes to everyone in the audience — including anyone who opted out of marketing email, since that isn’t an opt-out from the app.": "Chỉ tiêu đề và nội dung, gửi vào phần thông báo của người bán. Đến với mọi người trong danh sách — kể cả những ai đã từ chối nhận email tiếp thị, vì đó không phải là từ chối nhận thông báo trong ứng dụng.",
  "broadcasts.No per-address record for this one — it was sent before addresses were kept. The counts above are what was logged at the time.": "Không có bản ghi theo từng địa chỉ cho lần gửi này — nó được gửi trước khi hệ thống lưu địa chỉ. Các con số ở trên là những gì đã được ghi lại lúc đó.",
