  "spydeck.. Heart the winners to save them.": ". Bấm trái tim ở những mẫu tốt để lưu lại.",
  "spydeck.Tap the heart on any research card to save it here for later.": "Bấm trái tim trên bất kỳ thẻ nghiên cứu nào để lưu về đây dùng sau.",
  "spydeck.Hit “Create product” on any card to publish it as an Etsy draft — it’ll show here.": "Bấm “Tạo sản phẩm” trên một thẻ bất kỳ để đăng thành bản nháp Etsy — nó sẽ hiện ở đây.",
  "spydeck.Search any keyword to spy live Etsy listings — price, views and favorites, with the standouts flagged": "Tìm bất kỳ từ khoá nào để xem tin đăng Etsy theo thời gian thực — giá, lượt xem và lượt yêu thích, những mẫu nổi bật được đánh dấu",
  "spydeck.Category, price & sort search Etsy; sold/day & favorites filter results live.": "Nhóm hàng, giá và sắp xếp sẽ tìm trên Etsy; số bán/ngày và lượt yêu thích lọc kết quả ngay tại chỗ.",
  "spydeck.Reshuffle the feed for a fresh set of ideas — free and instant": "Xáo lại nguồn tin để có bộ ý tưởng mới — miễn phí và tức thì",
  "spydeck.Pull a brand-new batch of niches from Etsy (rate-limited)": "Lấy một loạt ngách hàng hoàn toàn mới từ Etsy (có giới hạn tần suất)",
  "spydeck.Couldn’t load today’s trending feed — this is a fetch problem, not an empty market.": "Không tải được nguồn xu hướng hôm nay — đây là lỗi tải dữ liệu, không phải thị trường trống.",
  "spydeck.Today’s trending feed isn’t available yet — try a search, or check back shortly.": "Nguồn xu hướng hôm nay chưa sẵn sàng — hãy thử tìm kiếm, hoặc quay lại sau ít phút.",

