  "dispatch., force-clear our link — it may still be in their queue otherwise.": ", hãy buộc gỡ liên kết của chúng ta — nếu không, nó có thể vẫn nằm trong hàng đợi của họ.",
  "dispatch.Their recall failed, so the Scan tag stays amber.": "Lệnh thu hồi của họ thất bại, nên thẻ Quét vẫn giữ màu hổ phách.",
  "dispatch.No dispatch actions recorded for this label yet.": "Chưa ghi nhận thao tác xuất hàng nào cho nhãn này.",
  "dispatch.No tracking numbers read off this file yet.": "Chưa đọc được mã vận đơn nào từ tệp này.",
  "dispatch.byeastside read the file and found no tracking label on it — re-send a clearer copy.": "byeastside đã đọc tệp và không tìm thấy nhãn vận đơn nào — hãy gửi lại bản rõ hơn.",
  "dispatch.An order appears here the moment it has a label nobody has scanned — or drop a label PDF anywhere on this page.": "Một đơn hàng xuất hiện ở đây ngay khi nó có nhãn mà chưa ai quét — hoặc bạn có thể thả tệp PDF nhãn vào bất kỳ đâu trên trang này.",
  "dispatch.Every label and what became of it — scanned, shipped, pulled off the board, or dropped in from outside — shows here.": "Mọi nhãn và kết cục của nó — đã quét, đã gửi, đã gỡ khỏi bảng, hay được thả vào từ bên ngoài — đều hiện ở đây.",
  "dispatch.Record that we scanned these ourselves — starts the buyer's tracking. Doesn't change what production is doing.": "Ghi nhận rằng chúng ta đã tự quét những kiện này — bắt đầu hành trình theo dõi cho người mua. Không thay đổi tiến độ sản xuất.",
