  "designer.Mockups, spec sheets, marked-up screenshots — anything that tells the designer what you want. Kept on the card and sent with a Pink Design push.": "Ảnh mẫu, bảng thông số, ảnh chụp màn hình có chú thích — bất cứ thứ gì cho nhà thiết kế biết bạn muốn gì. Được giữ trên thẻ và gửi kèm khi đẩy sang Pink Design.",
  "designer.No Ref/Task ID was recorded for this card, so status sync is off for it. Re-push to capture it.": "Thẻ này chưa ghi nhận Ref/Task ID nên việc đồng bộ trạng thái đang tắt. Hãy đẩy lại để lấy mã.",
  "designer.Pink returns only the Ref ID on push — on their test-webhook form, put this in": "Khi đẩy, Pink chỉ trả về Ref ID — trên biểu mẫu webhook thử nghiệm của họ, hãy điền mã này vào",
