  "digitizer.Drag the box on the canvas — corner to resize, top nub to rotate": "Kéo khung trên vùng làm việc — kéo góc để đổi kích thước, kéo núm trên để xoay",
  "digitizer.Your arrangement — drag to position. Generate merges the layers into one file.": "Bố cục của bạn — kéo để đặt vị trí. Lệnh Tạo sẽ gộp các lớp thành một tệp.",
  "digitizer.Turn artwork into an embroidery preview and a machine file — or build one from scratch.": "Chuyển thiết kế thành bản xem trước bản thêu và tệp máy — hoặc dựng mới từ đầu.",
  "digitizer.For complex art — a person digitizes the original artwork by hand. Sends the source file, not the auto-preview.": "Dành cho thiết kế phức tạp — một người sẽ số hoá thủ công từ thiết kế gốc. Gửi đi tệp nguồn, không phải bản xem trước tự động.",
