  "purchase.Nothing received or cancelled yet.": "Chưa có gì được nhận hoặc huỷ.",
  "purchase.No drafts, nothing in flight": "Không có bản nháp, không có đơn nào đang chạy",
  "purchase.No stock in any warehouse": "Không còn tồn ở bất kỳ kho nào",
  "purchase.Drop — not ordering this": "Bỏ — không đặt mục này",
  "purchase.Clear it off the board — the supplier is not contacted": "Gỡ khỏi bảng — không liên hệ nhà cung cấp",
  "purchase.Copy these items onto a new draft PO": "Sao chép các mặt hàng này sang đơn đặt hàng nháp mới",
  "purchase.Goods only. Freight and any tax are added by the supplier at placement.": "Chỉ tính hàng hoá. Cước vận chuyển và thuế do nhà cung cấp cộng thêm khi đặt.",
  "purchase.Book in everything this order is still waiting on and add it to the shelf": "Ghi nhận mọi thứ đơn này còn đang chờ và đưa lên kệ",
  "purchase.The shelf was empty when an order needed this, so it was added for you.": "Kệ đã hết hàng khi một đơn cần mặt hàng này, nên nó được thêm vào sẵn cho bạn.",
  "purchase.Items land here when an order runs stock short — or add them yourself with Add items.": "Các mặt hàng về đây khi một đơn làm thiếu tồn kho — hoặc bạn tự thêm bằng nút Thêm mặt hàng.",
  "purchase.Start one with New purchase order, or from a reorder suggestion above.": "Hãy tạo mới bằng Đơn đặt hàng mới, hoặc từ một gợi ý đặt lại ở trên.",
  "purchase.Restock low inventory — draft POs per supplier, place via S&S / Otto, receive into stock.": "Bổ sung hàng sắp hết — tạo đơn đặt hàng nháp theo từng nhà cung cấp, đặt qua S&S / Otto, rồi nhận vào kho.",
  "purchase.S&S have no tracking for this order yet — it hasn’t shipped.": "S&S chưa có mã vận đơn cho đơn này — hàng chưa được gửi đi.",
  "purchase.Built and recorded, but never transmitted — the supplier's live-order gate is off": "Đã dựng và ghi nhận, nhưng chưa hề gửi đi — cổng đặt hàng thật của nhà cung cấp đang tắt",
  "purchase.Placed against the supplier's SANDBOX environment, not the live account. No blanks are on their way — switch OTTOCAP_API_BASE to Otto's production host to order for real.": "Đã đặt trên môi trường SANDBOX của nhà cung cấp, không phải tài khoản thật. Không có phôi nào đang trên đường — hãy chuyển OTTOCAP_API_BASE sang máy chủ chính thức của Otto để đặt hàng thật.",
