  "sourcing.filled in by 'Read listing', or paste one": "được điền bởi 'Đọc tin đăng', hoặc bạn tự dán vào",
  "sourcing.Record a sample order — books its cost to the factory wallet": "Ghi nhận một đơn hàng mẫu — chi phí được hạch toán vào ví của xưởng",
  "sourcing.No sources saved yet. Add one to compare what a product lands at across suppliers.": "Chưa lưu nguồn nào. Hãy thêm một nguồn để so sánh giá về kho của một sản phẩm giữa các nhà cung cấp.",
  "sourcing.Nothing saved yet. Heart a listing in SpyDeck and it will show up here.": "Chưa lưu gì. Hãy bấm trái tim một tin đăng trong SpyDeck và nó sẽ hiện ở đây.",
  "sourcing.Where each product comes from and what it lands at, once freight is spread over the MOQ.": "Mỗi sản phẩm đến từ đâu và giá về kho là bao nhiêu, sau khi chia cước vận chuyển theo số lượng đặt tối thiểu.",
  "sourcing.Open the listing on Alibaba — their Contact Supplier is there. The search API returns no seller name.": "Mở tin đăng trên Alibaba — nút Liên hệ nhà cung cấp nằm ở đó. API tìm kiếm không trả về tên người bán.",

