  "siteContent.Saved — live within a minute.": "Đã lưu — có hiệu lực trong vòng một phút.",
  "siteContent.Never edited — showing shipped defaults.": "Chưa từng chỉnh sửa — đang hiển thị nội dung mặc định.",
  "siteContent.The first thing above the fold.": "Thứ đầu tiên người xem nhìn thấy.",
  "siteContent.The three-step strip.": "Dải ba bước.",
  "siteContent.The dark band at the foot of the page.": "Dải màu tối ở chân trang.",
  "siteContent.The saved figure isn’t loading.": "Hình đã lưu không tải được.",
  "siteContent.The public /features page. Every word on it is here.": "Trang /features công khai. Mọi chữ trên đó đều nằm ở đây.",
  "siteContent.The public /how-it-works page. Every word on it is here.": "Trang /how-it-works công khai. Mọi chữ trên đó đều nằm ở đây.",
  "siteContent.and public-read on the server.": "và cho phép đọc công khai trên máy chủ.",
  "siteContent.The band of figures under the hero, divided by rules. Five is what it fits before it wraps.": "Dải các con số dưới khối mở đầu, ngăn nhau bằng đường kẻ. Vừa được năm mục trước khi xuống dòng.",
  "siteContent.Quotes with a name and a role. The avatar is a placeholder circle by design — no invented photos.": "Các trích dẫn kèm tên và vai trò. Ảnh đại diện cố ý để là một vòng tròn trống — không dùng ảnh bịa đặt.",
  "siteContent.Status colours come from the label — keep the product’s own words (Draft, Pending, In process, Fulfilled) or the row renders grey.": "Màu trạng thái được suy ra từ nhãn — hãy giữ đúng các từ của sản phẩm (Draft, Pending, In process, Fulfilled) nếu không dòng sẽ hiển thị màu xám.",
  "siteContent.The section heading plus the four feature cards. The cards are fixed slots — edit their text, but their icons and layout stay in the design.": "Tiêu đề mục cùng bốn thẻ tính năng. Các thẻ là ô cố định — bạn sửa được chữ, còn biểu tượng và bố cục thì thuộc về thiết kế.",
  "siteContent.How sections arrive on the public pages. Which animation each section uses is set in the page code; the feel of each one is set here, and takes effect within a minute of saving.": "Cách các mục xuất hiện trên trang công khai. Mỗi mục dùng hiệu ứng nào là do mã nguồn trang quyết định; cảm giác của từng hiệu ứng được đặt ở đây, và có hiệu lực trong vòng một phút sau khi lưu.",
  "siteContent.Its URL was saved, but the browser can’t open it — usually the storage bucket / CDN isn’t public. Re-upload, or check": "Đường dẫn đã được lưu, nhưng trình duyệt không mở được — thường là do kho lưu trữ / CDN chưa ở chế độ công khai. Hãy tải lên lại, hoặc kiểm tra",
