  "catalogPrint.Every style in this book is priced.": "Mọi kiểu trong cuốn này đều đã có giá.",
  "catalogPrint.No colourway images on this style.": "Kiểu này chưa có ảnh theo màu.",
  "catalogPrint.No decoration methods set on this style": "Kiểu này chưa đặt phương pháp trang trí",
  "catalogPrint., or the swatches and panels print white.": ", nếu không các ô màu và mảng nền sẽ in ra màu trắng.",
  "catalogPrint.. Tick": ". Hãy tích",
  "catalogPrint.Nothing is published yet — publish some products or supplier styles first.": "Chưa có gì được đăng — hãy đăng một vài sản phẩm hoặc kiểu từ nhà cung cấp trước.",
  "catalogPrint.Put the name, copy and photo back to what the catalogue says": "Đưa tên, nội dung và ảnh trở lại đúng như trong danh mục",
  "catalogPrint.Rewrite names, copy, prices and photos for this catalogue. The product itself is untouched.": "Viết lại tên, nội dung, giá và ảnh cho riêng danh mục này. Bản thân sản phẩm không bị thay đổi.",
  "catalogPrint.The trade rate for the blank. Printing and embroidery are added on top of it.": "Giá sỉ của phôi. Chi phí in và thêu được cộng thêm lên trên.",
  "catalogPrint.Print-ready files go straight through. We digitise embroidery ourselves if you'd rather.": "Tệp sẵn sàng in sẽ được dùng thẳng. Chúng tôi tự số hoá bản thêu nếu bạn muốn.",
  "catalogPrint.Produced to order, packed, and tracking pushed back to your shop.": "Sản xuất theo đơn, đóng gói, và mã vận đơn được đẩy ngược về cửa hàng của bạn.",
  "catalogPrint.Blanks held and decorated to order — no minimums per design, and every piece printed, packed and shipped from one floor.": "Phôi được trữ sẵn và trang trí theo đơn — không yêu cầu số lượng tối thiểu cho mỗi thiết kế, và mọi sản phẩm đều được in, đóng gói và gửi đi từ cùng một xưởng.",
  "catalogPrint.Every sku in this catalogue is orderable as printed — the colour code beside each swatch is what we need.": "Mọi mã SKU trong danh mục này đều đặt được đúng như in — mã màu bên cạnh mỗi ô màu là thứ chúng tôi cần.",
