  "shipmentDetail.— and you can put it back.": "— và bạn có thể gắn lại.",
  "shipmentDetail.Open the full order this parcel belongs to": "Mở toàn bộ đơn hàng mà kiện này thuộc về",
  "shipmentDetail.Nothing has been bought for this parcel yet.": "Chưa mua gì cho kiện hàng này.",
  "shipmentDetail.The label was cancelled with the carrier and its file went with it.": "Nhãn đã được huỷ với bên vận chuyển và tệp nhãn cũng mất theo.",
  "shipmentDetail.Refund the postage with the carrier. This cannot be undone.": "Hoàn bưu phí với bên vận chuyển. Không thể hoàn tác.",
  "shipmentDetail.It was taken off this order, not refunded. The postage is still bought and the parcel is still moving.": "Nó đã được gỡ khỏi đơn hàng này, không phải hoàn tiền. Bưu phí vẫn đã mua và kiện hàng vẫn đang di chuyển.",
  "shipmentDetail.Take this tracking off the order so a correct label can be bought. The postage is NOT refunded, and this can be undone.": "Gỡ mã vận đơn này khỏi đơn hàng để có thể mua một nhãn đúng. Bưu phí KHÔNG được hoàn, và thao tác này có thể hoàn tác.",
  "shipmentDetail.If the carrier can’t find it, nothing changes. The marketplace isn’t told either — we no longer know if the buyer has this number.": "Nếu bên vận chuyển không tìm thấy, sẽ không có gì thay đổi. Sàn thương mại cũng không được thông báo — chúng ta không còn biết người mua có mã này hay không.",
  "shipmentDetail.Nothing matches its address or name. Orders that already have tracking aren’t offered, since a second number on one order means a parcel is unaccounted for.": "Không có gì khớp với địa chỉ hoặc tên của kiện. Các đơn đã có mã vận đơn không được đề xuất, vì hai mã trên cùng một đơn nghĩa là có một kiện không rõ tung tích.",
  "shipmentDetail.Bought on a test key: the tracking number and price are real in shape but nothing was ever charged, and the parcel will never move.": "Được mua bằng khoá thử nghiệm: mã vận đơn và giá có hình thức như thật nhưng chưa hề bị tính phí, và kiện hàng sẽ không bao giờ di chuyển.",

  // ── API playground, consignment, integrations, shipping label ─────────────
  "apiPlayground.Sandbox": "Sandbox",
  "apiPlayground.Live": "Thật",
