  "apiPlayground.Your API key": "Khoá API của bạn",
  "apiPlayground.API Explorer": "Trình khám phá API",
  "apiPlayground.Developer sections": "Các mục dành cho nhà phát triển",
  "apiPlayground.Getting started": "Bắt đầu",
  "apiPlayground.Build in the sandbox": "Phát triển trong môi trường sandbox",
  "apiPlayground.Go live": "Chuyển sang chế độ thật",
  "apiPlayground.Settings → API keys": "Cài đặt → Khoá API",
  "apiPlayground.Add a test key above to send.": "Thêm một khoá thử nghiệm ở trên để gửi yêu cầu.",
  "apiPlayground.A live key makes calls create real records.": "Khoá thật sẽ khiến các lệnh gọi tạo ra dữ liệu thật.",
  "apiPlayground.A sandbox key hits /api/test/* — no real orders, labels or charges.": "Khoá sandbox gọi vào /api/test/* — không tạo đơn hàng, nhãn hay khoản phí thật nào.",
  "apiPlayground.Two directions: pull orders": "Hai chiều: kéo đơn hàng về",
  "apiPlayground.a sales channel (Etsy/Shopify — Stores page), or let another system push orders": "một kênh bán (Etsy/Shopify — trang Cửa hàng), hoặc để một hệ thống khác đẩy đơn hàng vào",
  "apiPlayground.EGFUL via this API. The sandbox is for the second.": "EGFUL qua API này. Sandbox dùng cho trường hợp thứ hai.",
  "apiPlayground.orders. Use a test key while building.": "đơn hàng. Hãy dùng khoá thử nghiệm khi đang phát triển.",
  "apiPlayground.— a live key (egk_live_…) makes calls create": "— khoá thật (egk_live_…) sẽ khiến các lệnh gọi tạo ra",
  "apiPlayground.Every call hits /api/test/* — it validates auth and returns realistic responses but creates NO real orders, labels, or charges. Try the endpoints below.": "Mọi lệnh gọi đều vào /api/test/* — hệ thống kiểm tra xác thực và trả về phản hồi giống thật nhưng KHÔNG tạo đơn hàng, nhãn hay khoản phí thật nào. Hãy thử các endpoint bên dưới.",
  "apiPlayground.Generate a key (egk_test_…) in Settings → API keys, then paste it below. Send it on every request as the X-API-Key header.": "Tạo một khoá (egk_test_…) trong Cài đặt → Khoá API, rồi dán vào bên dưới. Gửi kèm khoá này trong mọi yêu cầu qua header X-API-Key.",
  "apiPlayground.Once your integration works, live access (a production key + real order endpoints) is enabled per-account — reach out and we'll turn it on.": "Khi tích hợp của bạn chạy được, quyền truy cập thật (khoá production + các endpoint đơn hàng thật) sẽ được bật theo từng tài khoản — hãy liên hệ và chúng tôi sẽ bật cho bạn.",
