  "consignment.No consigned stock yet.": "Chưa có hàng ký gửi nào.",
  "consignment.when a seller tells you stock is on the way — the declaration is what the counted quantities get checked against.": "khi người bán báo có hàng đang trên đường — bản khai báo chính là căn cứ để đối chiếu với số lượng đếm được.",
  "consignment.No bins defined yet — add some before receiving, or stock lands unassigned.": "Chưa khai báo ngăn kệ nào — hãy thêm trước khi nhận hàng, nếu không hàng về sẽ không được gán vị trí.",
  "consignment.We keep this declaration and check the counted quantities against it, so a short or over shipment shows as a discrepancy instead of quietly becoming the new truth.": "Chúng tôi giữ lại bản khai báo này và đối chiếu số lượng đếm được với nó, để một lô thiếu hoặc thừa hiện lên thành chênh lệch thay vì âm thầm trở thành số liệu mới.",
