  "integrations.at a real card key in": "tới một khoá thẻ có thật trong",
  "integrations.Keys with no integration card": "Các khoá không có thẻ tích hợp",
  "integrations.AI Assistant (Claude)": "Trợ lý AI (Claude)",
  "integrations.Anthropic API key": "Khoá API Anthropic",
  "integrations.Google AI API key": "Khoá API Google AI",
  "integrations.Image AI (Nano Banana)": "AI tạo ảnh (Nano Banana)",
  "integrations.Credentials are admin-only — sign in as an admin to see them.": "Thông tin đăng nhập chỉ dành cho quản trị — hãy đăng nhập bằng tài khoản quản trị để xem.",
  "integrations.Powers the account-aware auto-reply in seller Support chat.": "Vận hành tính năng tự trả lời theo dữ liệu tài khoản trong khung chat Hỗ trợ của người bán.",
  "integrations.Product images from a prompt, in staff’s own My EG chat. Not offered to sellers.": "Tạo ảnh sản phẩm từ câu mô tả, trong kênh My EG riêng của nhân viên. Không cung cấp cho người bán.",
  "integrations.A saved key overrides the server env. Get one from Google AI Studio. Testing renders a real image, so it costs about 3&cent;. Admin only.": "Khoá đã lưu sẽ ghi đè biến môi trường của máy chủ. Lấy khoá tại Google AI Studio. Việc thử sẽ dựng một ảnh thật nên tốn khoảng 3 xu. Chỉ quản trị.",
  "integrations.A saved key overrides the server env. Haiku 4.5 runs about a fifth of a cent per question. Admin only.": "Khoá đã lưu sẽ ghi đè biến môi trường của máy chủ. Haiku 4.5 tốn khoảng một phần năm xu cho mỗi câu hỏi. Chỉ quản trị.",
  "integrations.Saved, but not in use yet — this one is read when the API starts. Restart it, then this row is what’s live.": "Đã lưu, nhưng chưa được dùng — khoá này được đọc lúc API khởi động. Hãy khởi động lại, sau đó dòng này mới là dòng đang chạy.",
  "integrations.The key is set, but object storage isn’t configured — a generated image couldn’t be kept, so generation stays off.": "Khoá đã được đặt, nhưng kho lưu trữ đối tượng chưa được cấu hình — ảnh tạo ra sẽ không lưu được nên tính năng tạo ảnh vẫn tắt.",
  "integrations.These are configured on the server but name a card that doesn’t exist, so they can’t be edited here. Point their": "Các mục này được cấu hình trên máy chủ nhưng trỏ tới một thẻ không tồn tại, nên không sửa được ở đây. Hãy trỏ",
