  "label.What the empty box or mailer weighs — added to the contents": "Khối lượng của hộp hoặc túi rỗng — được cộng vào khối lượng hàng bên trong",
  "label.Name, street, then City, ST ZIP — the label uses exactly this. Ship-from is your saved warehouse address (Settings › Platform).": "Tên, địa chỉ, rồi Thành phố, Bang, Mã bưu chính — nhãn sẽ in đúng như vậy. Địa chỉ gửi đi là địa chỉ kho đã lưu của bạn (Cài đặt › Nền tảng).",
  "label.No warehouse ‘From’ address saved — set it in Settings › Platform before buying.": "Chưa lưu địa chỉ kho ‘Gửi từ’ — hãy đặt trong Cài đặt › Nền tảng trước khi mua nhãn.",
  "label.No rates for this parcel. Check the address and weight, and that a shipping provider is set up — Shippo, or USPS under Settings › API keys.": "Không có mức giá nào cho kiện này. Hãy kiểm tra địa chỉ, khối lượng, và xem đã thiết lập nhà vận chuyển chưa — Shippo, hoặc USPS trong Cài đặt › Khoá API.",
  "label.Buying here produces a sample label — it is not valid postage and nothing is charged. Switch USPS to Live in Settings › API keys when you are ready to ship for real.": "Mua ở đây chỉ tạo ra nhãn mẫu — nhãn này không có giá trị bưu chính và không bị tính phí. Hãy chuyển USPS sang chế độ Thật trong Cài đặt › Khoá API khi bạn sẵn sàng gửi hàng thật.",

