  "ledger.An invoice or PO number. Entering the same one twice records once, so a re-entered invoice can’t double-count.": "Số hoá đơn hoặc số đơn đặt hàng. Nhập cùng một số hai lần chỉ ghi nhận một lần, nên một hoá đơn nhập lại không thể bị tính đúp.",
