  "pushPartner.Opens a task on Pink Design’s board. They return finished files to this card.": "Mở một công việc trên bảng của Pink Design. Họ sẽ trả tệp hoàn thiện về thẻ này.",
  "pushPartner.The image above will be uploaded and sent as the design.": "Ảnh ở trên sẽ được tải lên và gửi đi làm thiết kế.",
  "pushPartner.No stored artwork — the image you attached below will be sent as the design.": "Không có thiết kế được lưu — ảnh bạn đính kèm bên dưới sẽ được gửi đi làm thiết kế.",
  "pushPartner.No stored artwork here. Attach an image under Reference files below and it'll be sent as the design.": "Ở đây không có thiết kế được lưu. Hãy đính kèm một ảnh ở mục Tệp tham chiếu bên dưới và nó sẽ được gửi đi làm thiết kế.",
  "pushPartner.No reference files on the card yet — add them above; the artwork still sends.": "Thẻ chưa có tệp tham chiếu nào — hãy thêm ở trên; phần thiết kế vẫn được gửi đi.",
  "pushPartner.The design partner isn't connected — add PINKDESIGN_API_KEY in Settings › Integrations.": "Đối tác thiết kế chưa được kết nối — hãy thêm PINKDESIGN_API_KEY trong Cài đặt › Tích hợp.",
  "pushPartner.Mockups, spec sheets, a marked-up screenshot — anything that tells their designer what you want. Sent alongside the artwork; if there’s no stored artwork, the first image here is sent as the design.": "Ảnh mẫu, bảng thông số, ảnh chụp màn hình có chú thích — bất cứ thứ gì cho nhà thiết kế của họ biết bạn muốn gì. Được gửi kèm với thiết kế; nếu không có thiết kế nào được lưu, ảnh đầu tiên ở đây sẽ được gửi đi làm thiết kế.",
