  "partnerSheets.No partner templates yet. Upload the workbook a partner sent you and map their columns to ours once — after that, exporting is one click.": "Chưa có mẫu đối tác nào. Hãy tải lên bảng tính mà đối tác gửi cho bạn và ánh xạ các cột của họ sang của chúng ta một lần — sau đó việc xuất dữ liệu chỉ còn một cú bấm.",
  "partnerSheets.The file carries their sheet names, section titles, headers and column order. It does not carry their cell colours or merged headings — those don’t survive being rebuilt, and a sheet that looked right but had lost a merge would be worse than one that plainly never had them.": "Tệp giữ lại tên trang tính, tiêu đề mục, tiêu đề cột và thứ tự cột của họ. Nó không giữ màu ô hay các tiêu đề đã gộp ô — những thứ đó không sống sót qua việc dựng lại, và một bảng trông có vẻ đúng nhưng đã mất phần gộp ô sẽ tệ hơn một bảng rõ ràng chưa từng có chúng.",
