  "planPackages.A new price applies from the next renewal — a month already charged stays at what it was charged. A plan priced at $0 never renews. Seller counts exclude deactivated accounts, which are never renewed.": "Giá mới áp dụng từ kỳ gia hạn kế tiếp — tháng đã bị tính phí vẫn giữ nguyên mức đã tính. Gói có giá $0 sẽ không bao giờ gia hạn. Số lượng người bán không tính các tài khoản đã vô hiệu hoá, vốn không bao giờ được gia hạn.",
