  "supplierTerms.. Worth re-asking before you commit to a buy.": ". Nên hỏi lại trước khi quyết định mua.",
  "supplierTerms.Paste what they wrote — price, MOQ, lead time, whatever they committed to.": "Dán đúng những gì họ viết — giá, số lượng tối thiểu, thời gian giao, bất cứ điều gì họ cam kết.",
  "supplierTerms.Paste it. Alibaba’s API exposes no messages, so this is the only copy — kept word for word rather than summarised.": "Hãy dán vào đây. API của Alibaba không cho truy cập tin nhắn, nên đây là bản duy nhất — được giữ nguyên văn thay vì tóm tắt.",
  "supplierTerms.What they committed to, as opposed to what the listing says. Unit price, MOQ and lead time stay on the row above.": "Những gì họ cam kết, khác với những gì tin đăng ghi. Đơn giá, số lượng tối thiểu và thời gian giao vẫn nằm ở dòng phía trên.",
