  "supportHours.Saved — applies immediately.": "Đã lưu — có hiệu lực ngay.",
  "supportHours.A date we’re out until — overrides the weekly hours until then. Clear it to cancel.": "Ngày chúng tôi nghỉ đến — sẽ ghi đè giờ làm việc hằng tuần cho tới lúc đó. Xoá đi để huỷ.",
  "supportHours.When the team is available. Outside these hours sellers see an out-of-office notice with the return time.": "Thời gian đội ngũ có mặt. Ngoài khung giờ này, người bán sẽ thấy thông báo ngoài giờ kèm thời điểm quay lại.",
