  "usage.Postage & blanks bill their exact amount into the wallet ledger, so these are actual dollars — the per-platform figures above estimate API-call cost from the rate you set.": "Bưu phí và phôi được ghi đúng số tiền thật vào sổ cái ví, nên đây là tiền thật — còn các con số theo nền tảng ở trên chỉ ước tính chi phí lệnh gọi API dựa trên đơn giá bạn đặt.",

