  "aiPricing.Off by default. While this is off, generation stays a factory tool and no seller can spend anything.": "Mặc định là tắt. Khi tắt, tính năng tạo ảnh chỉ là công cụ của xưởng và không người bán nào tiêu được đồng nào.",
  "aiPricing.Video generation stays admin-only and is not sold to sellers. A clip costs $0.20–$4.80 — up to fifteen images — and is rarely what turns into a listing.": "Tạo video chỉ dành cho quản trị và không bán cho người bán. Một đoạn video tốn $0,20–$4,80 — bằng tới mười lăm ảnh — và hiếm khi trở thành một tin đăng.",
